import { existsSync, readFileSync } from 'node:fs'
import { join } from 'node:path'
import glossaryRaw from '@/content/glossary.json'
import { profile, SITE_URL } from '@/lib/content'

export const dynamic = 'force-static'

type GlossaryTerm = { term: string; match: string[]; tip: string; source?: string | null }
const glossary = glossaryRaw as GlossaryTerm[]

// /llms-full.txt: the markdown mirrors generated by scripts/build-markdown.mjs (run on prebuild
// and committed under public/md), concatenated at build time into one document, followed by the
// glossary definitions (term and tip only) that the Prose popovers show on the HTML pages.
const MD_DIR = join(process.cwd(), 'public', 'md')

function readMarkdown(relative: string): string | null {
  const file = join(MD_DIR, relative)
  return existsSync(file) ? readFileSync(file, 'utf8').trim() : null
}

export function GET() {
  const { identity, links, meta, now } = profile
  const abs = (path: string) => `${SITE_URL}${path}`
  const order = [
    'index.md',
    'projects.md',
    'research.md',
    ...profile.projects.map((p) => `projects/${p.slug}.md`),
    'about.md',
    'resume.md',
  ]
  const sections = order.map(readMarkdown).filter((s): s is string => Boolean(s))
  if (sections.length === 0) {
    throw new Error('public/md is empty: run `node scripts/build-markdown.mjs` before building')
  }
  // The address is assembled on the client when a visitor asks for it; the mirrors must never carry it.
  const leak = sections.find((s) => s.includes(identity.email) || /mailto:/i.test(s))
  if (leak) {
    throw new Error('public/md carries an email address: regenerate it with `node scripts/build-markdown.mjs`')
  }

  const header = [
    `# ${identity.name}: full site content`,
    '',
    `> The complete content of ${SITE_URL} as one markdown document, generated from the same source as the HTML pages. Author: ${identity.name}. Last updated ${meta.lastUpdated} (profile version ${meta.version}). The short index is at ${abs('/llms.txt')}.`,
    '',
    `Contact paths: LinkedIn ${links.linkedin}, scheduling link ${links.scheduling}, contact card (vCard, carries the email address) ${abs('/shreya-boyane.vcf')}, resume PDF ${abs(links.resumePdf)}.`,
    '',
    `Now, as of ${now.date}:`,
    '',
    ...now.lines.map((line) => `- ${line}`),
    '',
    '',
  ].join('\n')

  const glossarySection = [
    `# Glossary (${glossary.length} terms)`,
    '',
    `Plain-English definitions of the terms used across this site, one sentence each, written by ${identity.name}. The HTML pages show them as popovers on the first mention of a term.`,
    '',
    ...glossary.map((t) => `- ${t.term}: ${t.tip}`),
  ].join('\n')

  return new Response(header + [...sections, glossarySection].join('\n\n---\n\n') + '\n', {
    headers: { 'Content-Type': 'text/plain; charset=utf-8' },
  })
}
